async function ensureAttachmentNode(preferred=null){
  const selected=preferred||selectedNode.value
  if(!selected)throw new Error('请先选择井场、井或井眼')
  if(Number(selected.node_id)>0)return selected
  const pid=Number(selected.field_id)||Number(fieldId.value)
  if(!pid)throw new Error('当前井场没有可用的工程权限范围')
  const existing=nodes.value.find(n=>n.node_type==='INBOX'&&!n.well_id&&Number(n.field_id)===pid)
  if(existing)return existing
  const created=await createLibraryNode(pid,{fieldId:pid,nodeType:'INBOX',parentId:selected.node_id,name:'工程资料',code:'INBOX'})
  await load()
  return nodes.value.find(n=>Number(n.node_id)===Number(created.node_id))||created
}
